settings.css:
:root{
  --mgpRed:#d81f2a; --euroBlue:#2277e0; --euroYellow:#ffd617;
  --fg:#ffffff;
  --panelBg:linear-gradient(158deg, rgba(13,19,31,.92) 0%, rgba(20,28,44,.86) 100%);
  --panelBorder:1px solid rgba(255,255,255,.14);
  --line:rgba(255,255,255,.28);
}
html,body{background:transparent!important;}
body{
  color:var(--fg)!important;
  font-family:'Saira Extra Condensed','Saira Condensed',sans-serif!important;
  letter-spacing:.3px;
}

/* ---- hide zoom controls + page title ---- */
body > div.p-3{display:none!important;}
body > div.bg-dark{display:none!important;}

/* ---- remove full-cell colour wash ---- */
table.bracket td{background:transparent!important; background-color:transparent!important;}

/* ---- connector lines ---- */
.bracket_box_line_in,.bracket_box_line_out,.bracket_box_line_down_left{border-color:var(--line)!important;}

/* ---- box = glass panel, accent strip by bracket type ---- */
.bracket_box .border-dark{
  border:var(--panelBorder)!important; border-radius:6px; overflow:hidden;
  background:var(--panelBg); box-shadow:0 6px 16px rgba(0,0,0,.5); position:relative;
}
.bracket_box .border-dark::before{
  content:''; position:absolute; top:0; left:0; right:0; height:3px; z-index:2;
  background:var(--euroBlue);                    /* Winners */
}
td.bg-danger  .bracket_box .border-dark::before{background:var(--mgpRed);}      /* Losers */
td.bg-warning .bracket_box .border-dark::before{background:var(--euroYellow);}  /* Championship */

/* ---- hide the box header (title / race number / results link) ---- */
.bracket_box .bg-dark{display:none!important;}
/* ---- hide the channel / frequency badge ---- */
.fpv_freq{display:none!important;}

/* ---- pilot list: numbered by finishing position ---- */
.bracket_box .bg-light{
  background:transparent!important;
  padding:8px 6px 4px!important;         /* room under the accent strip */
  counter-reset:pos;
}
.bracket_box .bg-light .text-dark{color:var(--fg)!important;}
.bracket_box .bg-info{
  background:linear-gradient(158deg, rgba(21,30,48,.9), rgba(28,38,58,.82))!important;
  color:var(--fg)!important;
  border:1px solid rgba(255,255,255,.10); border-radius:4px;
  display:flex; align-items:center; justify-content:flex-start; gap:8px;
  font-weight:600; margin-bottom:4px!important;
}
.bracket_box .bg-info::before{
  counter-increment:pos; content:counter(pos);
  font-weight:800; color:var(--euroYellow);
  min-width:1.1em; text-align:center; opacity:.95;
}
